questions.question:
What is the output of the following C++ program?

#include <iostream>
class Test {
public:
    static int count;
    Test() { count++; }
};
int Test::count = 0;
int main() {
    Test t1, t2, t3;
    std::cout << Test::count;
    return 0;
}

What is the output of the following program?

#include <iostream>
int main() {
    int a = 10, b = 20;
    int &ref = a;
    ref = b;
    std::cout << a << " " << b;
    return 0;
}

What is the output of the following program?

#include <iostream>
int main() {
    int arr[] = {10, 20, 30};
    int *p = arr;
    std::cout << *p++;
    return 0;
}
